function classifyAppInsightsFeature(raw){
  const key = String(raw || '').trim();
  if (!key) return '9. Noise / Passive';
  if (APP_INSIGHTS_CATALOGUE[key]) return APP_INSIGHTS_CATALOGUE[key];
  if (FEATURE_CATEGORY_MAP[key]) return FEATURE_CATEGORY_MAP[key];
  const low = key.toLowerCase();
  for (const rule of FEAT_CAT_PREFIX_RULES){
    if (low.startsWith(String(rule.prefix || '').toLowerCase())) return rule.category;
  }
  return classifyFeatureEvent(key);
}

/** All known features grouped by category (definitions, BC view, etc.). */
function buildFeatureCatalogueByCategory(){
  const grouped = {};
  const add = (raw, cat) => {
    if (!cat) return;
    if (!grouped[cat]) grouped[cat] = [];
    if (grouped[cat].indexOf(raw) === -1) grouped[cat].push(raw);
  };
  for (const [raw, cat] of Object.entries(APP_INSIGHTS_CATALOGUE)) add(raw, cat);
  for (const [raw, cat] of Object.entries(FEATURE_CATEGORY_MAP)) add(raw, cat);
  for (const rule of FEAT_CAT_PREFIX_RULES){
    add(String(rule.prefix) + '*', rule.category);
  }
  return grouped;
}

function featDescription(raw){
  const key = String(raw || '').trim();
  if (!key) return '';
  if (FEATURE_DESCRIPTIONS[key]) return FEATURE_DESCRIPTIONS[key];
  const aliasTag = FEATURE_TAG_ALIASES[key];
  if (aliasTag && FEATURE_DESCRIPTIONS[aliasTag]) return FEATURE_DESCRIPTIONS[aliasTag];
  const autoTag = key.replace(/\*$/,'').replace(/-/g,'_').toUpperCase();
  if (FEATURE_DESCRIPTIONS[autoTag]) return FEATURE_DESCRIPTIONS[autoTag];
  const low = key.toLowerCase();
  for (const pfx of Object.keys(FEATURE_PREFIX_DESCRIPTIONS)){
    if (low.startsWith(pfx)) return FEATURE_PREFIX_DESCRIPTIONS[pfx];
  }
  return '';
}

function featNameHtml(raw, extraClass){
  const lbl = escapeHtml(featLabel(raw));
  const desc = featDescription(raw);
  const cls = extraClass ? ('feat-feat-name ' + extraClass) : 'feat-feat-name';
  if (!desc) return '<span class="' + cls + '">' + lbl + '</span>';
  return '<span class="' + cls + '" title="' + escapeHtmlAttr(desc) + '">' + lbl + '</span>';
}
